function contarEmFluxo(linhas, condicao) {
  let total = 0
  for (const linha of linhas) {
    if (condicao(linha)) total += 1
  }
  return total
}

function somarEmCentavos(valores) {
  let total = 0
  for (const valor of valores) {
    total += Math.round(valor * 100)
  }
  return total
}

