const BYTES_POR_LINHA = 64

function linhasDeCache(totalDeElementos, bytesPorElemento, passo) {
  if (!Number.isInteger(totalDeElementos) || totalDeElementos < 0) return null
  if (!Number.isInteger(bytesPorElemento) || bytesPorElemento <= 0) return null
  if (!Number.isInteger(passo) || passo <= 0) return null

  const linhas = new Set()

  for (let indice = 0; indice < totalDeElementos; indice += passo) {
    linhas.add(Math.floor((indice * bytesPorElemento) / BYTES_POR_LINHA))
  }

  return linhas.size
}

