questions.solution:
function planejarLotes(ids, tamanho) {
  if (!(tamanho > 0)) throw new Error('tamanho de lote precisa ser maior que zero')

  const lotes = []
  for (let inicio = 0; inicio < ids.length; inicio += tamanho) {
    lotes.push(ids.slice(inicio, inicio + tamanho))
  }
  return lotes
}

function tempoEstimado(ids, tamanho, msPorIda) {
  // O custo está no número de idas, não no tamanho de cada uma.
  return planejarLotes(ids, tamanho).length * msPorIda
}
